get_tax_settings.code:
use WebCommander\Sdk\Resources\TaxSettings\TaxSettings;

$response = TaxSettings::getTaxSettings($client);

$settings = $response->map['tax_settings'];
echo $settings['default_country'], ' ', $settings['default_tax_code'], PHP_EOL;
echo $settings['tax_message'], PHP_EOL;

put_tax_settings.code:
use WebCommander\Sdk\Resources\TaxSettings\TaxSettings;

$response = TaxSettings::putTaxSettings($client, [
    'settings' => ['tax_message' => 'All prices include GST'],
]);

echo $response->map['tax_settings']['tax_message'], PHP_EOL;
